-- ============================================================================
-- Les liens de catalogue que la liste d'hôtes avait jetés
--
-- Jusqu'au 21/10/2026 le racleur reconnaissait un catalogue du réseau par une
-- liste de sept hôtes, fermée. Elle ignorait en silence tout lien vers bianco,
-- canto, bettini, cgecaf, ephemera, madrid-santos, lidiap et ficedl.info
-- lui-même — huit sites de la même fédération. Les 623 descripteurs relevés
-- avant la correction portaient donc une fraction de leurs liens.
--
-- Relecture des fiches le 22/10/2026, une à la fois, **dix secondes entre deux
-- requêtes** : c'est le `Crawl-delay` que robots.txt demande, et le racleur
-- l'obéit (1 h 36 pour 573 fiches ; la source a coupé trois fois de suite à la
-- 573e, le relevé s'est arrêté, le cache a permis de reprendre). Seuls les
-- liens sont relus : depuis le 18/10 une fiche ne sert plus ses libellés, et
-- les relire ici les écraserait par du vide.
--
-- UNION, PAS REMPLACEMENT. Le relevé frais retire 309 adresses, dont 305 sont
-- des DOUBLONS DE FORME : notre copie portait `ml.ficedl.info/?mot3` ET
-- `ml.ficedl.info/mot3.html`, deux adresses pour une même ressource, et la
-- source n'en affiche plus qu'une. Celles-là partent. Les autres pointent vers
-- une ressource unique que la source n'affiche plus : elles restent, avec
-- `lien_retire_de_la_source:2026-10-22`. Elles ont été relevées sur la source
-- le 03/09 — on n'invente rien — et depuis le 18/10 la source retire des liens
-- de ses fiches pour soulager son serveur, ce qui ne rend pas les ressources
-- fausses.
--
-- `harvested_at` n'est pas touché : il date l'aspiration des LIBELLÉS.
-- Les descripteurs relevés après la correction (les 35 du 21/10 et les 53
-- langues du 22/10) avaient déjà leurs liens complets et ne sont pas ici.
-- ============================================================================

UPDATE public.ficedl_thesaurus_terms SET catalog_links = '[{"name":"Ce mot dans le catalogue du CIRA Lausanne","href":"https://www.cira.ch/catalogue/index.php?lvl=categ_see&id=5"},{"name":"Ce mot dans le catalogue du CIRA Marseille","href":"https://bibliotheque.cira-marseille.info/opac_css/index.php?lvl=categ_see&id=7112"},{"name":"Placard : affiches anarchistes","href":"https://placard.ficedl.info/mot98.html"},{"name":"Ce mot dans le site Cartoliste","href":"https://cartoliste.ficedl.info/mot538.html"},{"name":"Ce mot dans les archives du Monde libertaire","href":"https://ml.ficedl.info/?mot3"},{"name":"Ce mot dans le catalogue du CCL","href":"https://lille.cybertaria.org/biblio/spip.php?mot97"},{"name":"Ce mot sur RAForum","href":"https://archives.cira-marseille.info/raforum/spip.php?mot370"}]', import_flags = '["libelles_rafraichis:2026-10-19","ro_de_la_page_export","liens_relus:2026-10-22"]' WHERE mot_id = 'mot1';
